import React, { useState, useEffect, useRef } from 'react'

const TypewriterText = ({ children, speed = 10, delay = 0 , classn=''}) => {
  const [displayedText, setDisplayedText] = useState('')
  const [currentIndex, setCurrentIndex] = useState(0)
  const [started, setStarted] = useState(false)
  const [showCursor, setShowCursor] = useState(true)
  const [isVisible, setIsVisible] = useState(false)
  const ref = useRef(null)

  // Convert children to string properly
  const text = typeof children === 'string' 
    ? children 
    : React.Children.toArray(children).join('')

  // Intersection Observer to detect visibility
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      {
        threshold: 0.1, // Trigger when 10% of element is visible
      }
    )

    if (ref.current) {
      observer.observe(ref.current)
    }

    return () => {
      if (ref.current) {
        observer.unobserve(ref.current)
      }
    }
  }, [])

  useEffect(() => {
    // Only start if visible
    if (isVisible && !started && delay > 0) {
      const delayTimeout = setTimeout(() => setStarted(true), delay)
      return () => clearTimeout(delayTimeout)
    } else if (isVisible) {
      setStarted(true)
    }
  }, [delay, started, isVisible])

  useEffect(() => {
    if (started && currentIndex < text.length) {
      const timeout = setTimeout(() => {
        setDisplayedText(prevText => prevText + text[currentIndex])
        setCurrentIndex(prevIndex => prevIndex + 1)
      }, speed)

      return () => clearTimeout(timeout)
    }
  }, [currentIndex, speed, text, started])

  useEffect(() => {
    const cursorInterval = setInterval(() => {
      setShowCursor(prev => !prev)
    }, 500)
    return () => clearInterval(cursorInterval)
  }, [])

  return (
    <span ref={ref}>
      <span style={{ whiteSpace: 'pre-wrap' }} className='{classn}'>{displayedText}</span>
      <span style={{ opacity: showCursor ? 1 : 0 }}> █</span>
    </span>
  )
}

export default TypewriterText
